import{z as o,x as s,o as A,c as p,q as B,j as i,D as l,d as E,s as r,S as t,b as e}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"回放缓冲与经验回放","description":"","frontmatter":{"title":"回放缓冲与经验回放","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/continual-replay-buffer.md","filePath":"llm/continual-replay-buffer.md","lastUpdated":1791413859000}'),d={name:"llm/continual-replay-buffer.md"};function m(C,a,D,f,u,h){const n=s("Mermaid");return A(),p("div",null,[a[2]||(a[2]=B('<h1 id="回放缓冲与经验回放" tabindex="-1">回放缓冲与经验回放 <a class="header-anchor" href="#回放缓冲与经验回放" aria-label="Permalink to &quot;回放缓冲与经验回放&quot;">​</a></h1><div class="epigraph"><p>与其计算旧任务哪里重要，不如把旧数据的一小撮一直带在身上；缓冲区把序列问题重新近似成联合问题。</p><footer>—— 据 Robins 1995、Rolnick 等 2019 整理</footer></div><p><a href="/llm/continual-ewc-family">上一课</a>把约束设在参数空间里，代价是要估重要性、且保护只是间接的。回放走相反的路：既然旧梯度与新梯度冲突，就在每个批次里把少量旧样本混回去，让旧梯度直接出现在更新里。主干<a href="/llm/continual-replay">持续学习与回放</a>一课已论证语言模型上这是默认起手式；本课深入缓冲区本身的工程：留什么、按什么比例混、以及这个缓冲区在账面上欠了什么。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>缓冲区有预算上限 \\(k\\)，数据流无限长，于是两个分配问题同时出现。纵向：流走远了，早期任务的样本占比自然趋向零，旧任务重新暴露在遗忘下。横向：同一时刻有多个来源，高流量来源会挤掉低流量来源，长尾任务无声消失。混入比例是第三个自由度：旧样本混太少没有保护，混太多新任务学不动。三处都错时，现象往往是「回放了但没起作用」，根因不在方法而在配额。</p><p><span class="marginnote">蓄水池采样可以想象成「掷骰子决定去留」：第 \\(n\\) 个到达的样本以 \\(k/n\\) 的概率挤掉池中随机一位。流走得越远，早期样本被换掉的概率越小，池子最终近似整条流的均匀缩影——而且不需要预先知道流到底有多长。</span></p><h3 id="留什么" tabindex="-1">留什么 <a class="header-anchor" href="#留什么" aria-label="Permalink to &quot;留什么&quot;">​</a></h3><p>最朴素的均匀蓄水池采样给第 \\(n\\) 个到达的样本 \\(k/n\\) 的入池概率，缓冲区在任意时刻近似是历史流的均匀样本。它的缺陷是均匀不等于均衡：任务大小悬殊时，小任务在池里只剩几个样本。任务感知的配额按任务或按月分桶，桶内再蓄水池。打分式策略更进一步：iCaRL（Rebuffi 等 2017）按离特征均值近挑「原型」样本；GSS（Aljundi 等 2019）按样本梯度与缓冲区梯度的余弦，留下不互相打架的。打分式更强也更贵，打分器自己还会过时。</p><p><span class="marginnote">Rolnick 等 2019 的实验口径：每个新样本配一条旧回放样本，就能在多个图像数据集序列上接近联合训练下界。回放的保护力主要来自把旧梯度方向放回批次，不需要复现整个旧分布。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>批次构造上，设本步从新流取 \\(m\\) 条、从缓冲取 \\(r\\) 条。固定 \\(r/m\\) 是最常见做法，但不等于新旧贡献均衡：损失尺度与样本难度都在变，更稳的是按损失加权——旧、新两路各自归一，再按目标贡献比合成。比例跟着任务窗口调：新任务初期回放占比自然高，后期压回去。</p><p>缓冲区是数据资产，就要有资产账：每条样本带来源、任务标签、入库时间与许可标记；淘汰按桶配额腾位而非全局随机，遗忘曲线才能按任务归因。</p>',12)),(A(),i(t,null,{default:l(()=>[r(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20STREAM%5B%22%E6%96%B0%E6%A0%B7%E6%9C%AC%E6%B5%81%22%5D%20--%3E%20POLICY%5B%22%E5%85%A5%E5%BA%93%E7%AD%96%E7%95%A5%EF%BC%9A%E9%85%8D%E9%A2%9D%2B%E8%93%84%E6%B0%B4%E6%B1%A0%2B%E6%89%93%E5%88%86%22%5D%0A%20%20POLICY%20--%3E%20BUF%5B%22%E7%BC%93%E5%86%B2%E5%8C%BA%EF%BC%88%E5%B8%A6%E6%9D%A5%E6%BA%90%E4%B8%8E%E8%AE%B8%E5%8F%AF%E8%B4%A6%EF%BC%89%22%5D%0A%20%20BUF%20--%3E%20MIX%5B%22%E6%89%B9%E6%AC%A1%E6%B7%B7%E5%90%88%E5%99%A8%22%5D%0A%20%20STREAM%20--%3E%20MIX%0A%20%20MIX%20--%3E%20Q%7B%22%E6%97%A7%E8%B7%AF%E6%8D%9F%E5%A4%B1%E6%9D%83%E9%87%8D%E6%98%AF%E5%90%A6%E5%9D%87%E8%A1%A1%3F%22%7D%0A%20%20Q%20--%3E%7C%E5%90%A6%7C%20REW%5B%22%E6%8C%89%E6%8D%9F%E5%A4%B1%E9%87%8D%E5%8A%A0%E6%9D%83%22%5D%0A%20%20REW%20--%3E%20BATCH%5B%22%E8%AE%AD%E7%BB%83%E6%89%B9%E6%AC%A1%22%5D%0A%20%20Q%20--%3E%7C%E6%98%AF%7C%20BATCH%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("回放为什么用很小的缓冲就能起效："),e("a",{href:"/llm/continual-forgetting-mechanism"},"第一课"),E("把遗忘拆成方向与步长，回放的作用是把旧任务的下降方向放回每一步，新参数在「两头都降」的方向上找折中。它近似的是联合目标的采样，而非重建旧分布；方向对了，样本数量不敏感。打分式策略的有效面同理：挑不与新梯度打架的旧样本，等于手工去掉最冲突的方向。")],-1)),a[5]||(a[5]=e("p",null,"「有没有旧样本」如何改变一步更新的走向，可以这样对比着看：",-1)),(A(),i(t,null,{default:l(()=>[r(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%8F%82%E6%95%B0%E5%BD%93%E5%89%8D%E4%BD%8D%E7%BD%AE%22%5D%20--%3E%20Q%7B%22%E6%9C%AC%E6%AD%A5%E6%89%B9%E6%AC%A1%E9%87%8C%E6%9C%89%E6%B2%A1%E6%9C%89%E6%97%A7%E6%A0%B7%E6%9C%AC%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%B2%A1%E6%9C%89%22%7C%20N%5B%22%E5%8F%AA%E8%A7%81%E6%96%B0%E4%BB%BB%E5%8A%A1%E6%A2%AF%E5%BA%A6%22%5D%20--%3E%20N2%5B%22%E5%8F%82%E6%95%B0%E8%B5%B0%E8%BF%9B%E6%96%B0%E7%9B%86%E5%9C%B0%2C%E6%97%A7%E4%BB%BB%E5%8A%A1%E7%9A%84%E8%A7%A3%E8%A2%AB%E8%A6%86%E7%9B%96%22%5D%0A%20%20Q%20--%3E%7C%22%E6%9C%89%22%7C%20B%5B%22%E6%96%B0%E6%97%A7%E4%B8%A4%E7%BB%84%E6%A2%AF%E5%BA%A6%E5%90%8C%E6%97%B6%E5%9C%A8%E5%9C%BA%22%5D%20--%3E%20C%5B%22%E5%8F%96%E4%B8%A4%E5%A4%B4%E9%83%BD%E4%B8%8B%E9%99%8D%E7%9A%84%E6%8A%98%E4%B8%AD%E6%96%B9%E5%90%91%22%5D%20--%3E%20D%5B%22%E6%97%A7%E8%A7%A3%E8%A2%AB%E8%BF%91%E4%BC%BC%E4%BF%9D%E4%BD%8F%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=B('<p><span class="marginnote">为什么配比值得精调：假设一批 32 条全是新样本，旧任务在这一步梯度里的话语权是零；混入 8 条旧样本，旧方向立刻拿到四分之一的票数。抗遗忘与学新速度，就是在这张「票数表」上来回换的。</span></p><p>回放还有一层间接保护：旧样本把表示钉在旧任务可用的区域。这层保护对表示漂移——<a href="/llm/continual-forgetting-mechanism">第一课</a>三条通路里最隐蔽的一条——比对参数位移更有效，恰补上 EWC 对角近似的短板，两者叠加时正则的 \\(\\lambda\\) 可整体下调。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>缓冲区的账单首先是隐私：它原样保留了历史提示与回答，谁有权进池、保留多久、收到删除请求怎么办，是生产环里最常被省略也最致命的一节，本课程后面有专课处理。其次是陈化：旧样本的格式停在入库那天，池子越老，回放越像在维护一门旧方言。第三是可塑性税：打分器把「对旧任务友好」的偏置传给选择，新任务早期学得慢，别把这笔账记在学习率头上。</p><p><span class="marginnote">「缓冲区泄漏」为什么格外严重：回放池里存的不是抽象特征，而是一条条能直接阅读的原样提示与回答。它相当于把历史流量的高浓度样本集中放进一个小文件，访问控制和保留期必须按最高敏感级来设。</span></p><p>任务边界模糊时，配额与打分失去主键，只能退到按时间分桶的均匀蓄水池——保护变弱但仍有。最后，回放不创造能力：新能力仍取决于新数据的质量，那是<a href="/llm/synthetic-engineering-map">上一门课程</a>那张配方地图管的事。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>回放把序列问题近似成联合问题：混入少量旧样本，把旧梯度方向放回每一步更新。</li><li>缓冲区三个自由度：入库配额（任务/时间桶）、挑选策略（均匀、原型、梯度相容）、混入与加权比例。</li><li>保护力来自方向而非分布：每新样本配一条旧样本量级即可显著抗遗忘。</li><li>正则与回放互补：回放补表示漂移与耦合方向，正则补无数据场景。</li><li>缓冲区是带账的数据资产：来源、许可、保留期、删除义务，缺账的回放是负债。</li><li>出处：Robins 1995（rehearsal）；Rebuffi 等 2017（iCaRL）；Aljundi 等 2019（GSS）；Rolnick 等 2019（Experience Replay）。</li></ul>',8))])}const F=o(d,[["render",m]]);export{b as __pageData,F as default};
